using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.Script.Serialization;

internal static class MouseLightingProtocolTests {
 static int checks;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,message);}
 static Dictionary<string,object> O(params object[] pairs){return GearLinkWorker.Obj(pairs);}
 static Dictionary<string,object> Before(int pid=7548,int mode=0){return O("modelPid",pid,"lightingSoftwareMode",false,"windowsLightingEnabled",false,"lighting",O("currentMode",mode,"area",0,"brightness",20,"color",new[]{11,22,33},"direction",1,"random",false,"speed",173));}
 static Dictionary<string,object> Recipe(Dictionary<string,object> state){return (Dictionary<string,object>)state["lighting"];}
 static Dictionary<string,object> Copy(Dictionary<string,object> value){var json=new JavaScriptSerializer();return json.Deserialize<Dictionary<string,object>>(json.Serialize(value));}
 static Dictionary<string,object> After(Dictionary<string,object> before,byte[] bytes){var result=Copy(before);result["lighting"]=GearLinkWorker.ParseMouseLighting(new byte[]{18,3,0,0,bytes[4],bytes[5],bytes[6],bytes[7],bytes[8],199,bytes[9],bytes[10],bytes[11]});return result;}
 static int Main(){try {
  foreach(int pid in new[]{7546,7548})foreach(int mode in new[]{0,1,2,4,6}) {
   var before=Before(pid);string originalBefore=new JavaScriptSerializer().Serialize(before);var value=O("effect",mode,"brightness",47);if(GearLinkWorker.MouseLightingHasColor(mode))value["color"]=new[]{40,50,60};byte[] bytes=GearLinkWorker.BuildMouseLighting(value,before);Check(new JavaScriptSerializer().Serialize(before)==originalBefore,"encoder never mutates the fresh read evidence");
   Check(bytes.Take(6).SequenceEqual(new byte[]{81,40,0,0,(byte)mode,47})&&bytes[9]==1&&bytes[10]==0&&bytes[11]==173,"exact command plus fresh preserved fields: "+pid+"/"+mode);
   Check(bytes.Skip(6).Take(3).SequenceEqual((mode==2?new[]{0,0,0}:mode==6?new[]{11,22,33}:new[]{40,50,60}).Select(x=>(byte)x)),"effect-specific RGB encoding");Check(GearLinkWorker.IsMouseLightingWrite("mouse",bytes)&&!GearLinkWorker.IsMouseLightingWrite("keyboard",bytes),"write allowlist is exact collection");var after=After(before,bytes);Check(GearLinkWorker.MatchesMouseLighting(value,before,after),"full normalized readback matches");
   foreach(string field in new[]{"currentMode","brightness","color","direction","random","speed"}){var changed=Copy(after);Recipe(changed)[field]=field=="random"?(object)true:field=="color"?(object)new[]{1,2,3}:field=="direction"?0:field=="speed"?172:255;Check(!GearLinkWorker.MatchesMouseLighting(value,before,changed),"unrequested/readback difference is never confirmed: "+field);}
   var supported=GearLinkWorker.MouseLightingOptions(pid).Cast<Dictionary<string,object>>().ToArray();Check(supported.Select(item=>(int)item["value"]).SequenceEqual(new[]{0,1,2,4,6})&&supported.All(item=>!(bool)item["speed"]&&!(bool)item["direction"]&&!(bool)item["random"]),"metadata exposes only exact five-effect model capabilities");
  }
  foreach(int pid in new[]{0,7489,7547,7549,7588,65535}){Check(!GearLinkWorker.MouseLightingReady(pid,Before(pid))&&GearLinkWorker.MouseLightingOptions(pid).Length==0,"related/other models receive no capability");Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20),Before(pid)),"unsupported model encoder refuses I/O");}
  foreach(int mode in new[]{-1,3,5,7,240,241})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",mode,"brightness",20),Before()),"generic enum is not a model support claim");
  foreach(object invalid in new object[]{null,"1",1.0,true,256})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",invalid,"brightness",20),Before()),"effect is an exact integer");
  foreach(object invalid in new object[]{null,"20",20.0,true,-1,101})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",invalid),Before()),"brightness integer range enforced");
  foreach(int brightness in new[]{0,1,20,47,100})Check(GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",brightness),Before())[5]==brightness,"all verified brightness values including zero retained");
  foreach(string field in new[]{"speed","direction","random","area","owner"})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20,field,0),Before()),"unsupported request field is rejected: "+field);
  foreach(int mode in new[]{2,6})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",mode,"brightness",20,"color",new[]{1,2,3}),Before()),"cycle/battery do not accept a fabricated color editor");
  foreach(object rgb in new object[]{null,"#000000",new[]{1,2},new[]{1,2,3,4},new[]{256,0,0},new object[]{1,2,3.0}})Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20,"color",rgb),Before()),"RGB is exactly three integer bytes");
  foreach(string owner in new[]{"lightingSoftwareMode","windowsLightingEnabled"})foreach(object invalid in new object[]{true,null,"false",0}){var before=Before();before[owner]=invalid;Check(!GearLinkWorker.MouseLightingReady(7548,before),"owner must be confirmed false");Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20),before),"no implicit owner takeover");}
  foreach(string field in new[]{"area","currentMode","brightness","speed","direction","color","random"}){var before=Before();Recipe(before).Remove(field);Check(!GearLinkWorker.MouseLightingReady(7548,before),"entire preserved recipe required: "+field);Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20),before),"missing fields reject before encoding");}
  var random=Before();Recipe(random)["random"]=true;var randomBytes=GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20),random);Check(randomBytes.Skip(6).Take(3).All(b=>b==0)&&randomBytes[10]==1&&randomBytes[9]==1&&randomBytes[11]==173,"random flag preserved with protocol-required zero RGB");Reject(()=>GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20,"color",new[]{1,2,3}),random),"random mode cannot masquerade as fixed color");
  var same=Before();Check(GearLinkWorker.MatchesMouseLighting(O("effect",0,"brightness",20,"color",new[]{11,22,33}),same,same),"same-value request can be a true no-op");Recipe(same)["color"]=new[]{0,0,0};Recipe(same)["brightness"]=0;Check(GearLinkWorker.MatchesMouseLighting(O("effect",0,"brightness",0,"color",new[]{0,0,0}),same,same),"black/zero is a valid no-op");
  var packet=GearLinkWorker.BuildMouseLighting(O("effect",1,"brightness",20),Before());foreach(int index in new[]{0,1,2,3,4,5,9,10}){var changed=(byte[])packet.Clone();changed[index]=255;Check(!GearLinkWorker.IsMouseLightingWrite("mouse",changed),"malformed command rejected: "+index);}Check(!GearLinkWorker.IsMouseLightingWrite("mouse",null)&&!GearLinkWorker.IsMouseLightingWrite("mouse",new byte[11]),"missing/truncated packet rejected");
  var state=O("pid",7548,"setCapabilities",new[]{"staticLighting"});var snapshot=Before();var caps=new List<string>{"lighting","lightingSoftwareMode","windowsLightingEnabled"};GearLinkWorker.AddMouseLightingCapabilities("mouse",true,state,snapshot,caps);Check(((string[])state["setCapabilities"]).Contains("mouseLighting")&&(bool)snapshot["mouseLightingProtocolAvailable"],"complete fresh read exposes a protocol-backed setter");GearLinkWorker.AddMouseLightingCapabilities("mouse",true,state,snapshot,caps);Check(((string[])state["setCapabilities"]).Count(item=>item=="mouseLighting")==1,"capability helper does not duplicate entries");foreach(string cap in caps){var missing=caps.Where(item=>item!=cap).ToList();GearLinkWorker.AddMouseLightingCapabilities("mouse",true,state,snapshot,missing);Check(!((string[])state["setCapabilities"]).Contains("mouseLighting")&&!(bool)snapshot["mouseLightingProtocolAvailable"],"partial GET never exposes write: "+cap);}GearLinkWorker.AddMouseLightingCapabilities("mouse",false,state,snapshot,caps);Check(!((string[])state["setCapabilities"]).Contains("mouseLighting"),"offline never exposes write");
  Console.WriteLine(new JavaScriptSerializer().Serialize(new{ok=true,checks=checks,hidOpened=0,hardwareWrites=0}));return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
